            [o1, o2] = asils.relations.nav.jacobi_eig4(reshape(x(1:16), 4, 4).');
            y = [reshape(o1, [], 1); reshape((o2).', [], 1)];
        case 'nav::quest'
            [o1, o2] = asils.relations.nav.quest(reshape(x(1:48), 3, 16).', reshape(x(49:96), 3, 16).', reshape(x(97:112), 16, 1), x(113));
            y = [reshape(o1, [], 1); double(o2)];
        case 'nav::gmst_rot'
            [o1] = asils.relations.nav.gmst_rot(x(1));
            y = [reshape((o1).', [], 1)];
        case 'nav::prec_rot'
            [o1] = asils.relations.nav.prec_rot(x(1));
            y = [reshape((o1).', [], 1)];
        case 'nav::eci2ecef'
            [o1] = asils.relations.nav.eci2ecef(x(1));
            y = [reshape((o1).', [], 1)];
        case 'nav::triad'
            [o1, o2] = asils.relations.nav.triad(reshape(x(1:3), 3, 1), reshape(x(4:6), 3, 1), reshape(x(7:9), 3, 1), reshape(x(10:12), 3, 1));
            y = [reshape(o1, [], 1); double(o2)];
        case 'pnt::gp_5'
            [o1] = asils.relations.pnt.gp_5(reshape(x(1:5), 5, 1));
            y = [double(o1)];
        case 'risk::rk4_0'
            [o1] = asils.relations.risk.rk4_0(reshape(x(1:7), 7, 1));
            y = [double(o1)];
        case 'shared::fromdcm'
            [o1] = asils.relations.shared.fromdcm(reshape(x(1:9), 3, 3).');
            y = [reshape(o1, [], 1)];
        case 'shared::fromrotvec'
            [o1] = asils.relations.shared.fromrotvec(reshape(x(1:3), 3, 1));
            y = [reshape(o1, [], 1)];
        case 'shared::modes_enter'
            [o1] = asils.relations.shared.modes_enter(struct('mode', {x(1)}, 't', {x(2)}, 't_mode', {x(3)}, 'hold', {x(4)}, 'ho', {(x(5) ~= 0)}, 'ho_t', {x(6)}, 'ad_ok', {(x(7) ~= 0)}, 'n_rej', {x(8)}, 'i_q', {reshape(x(9:11), 3, 1)}, 'sz_sum', {x(12)}, 'sz_n', {x(13)}, 'sz_t0', {x(14)}, 'sigma', {x(15)}, 's_prop', {reshape(x(16:18), 3, 1)}, 's_prop_ok', {(x(19) ~= 0)}, 'acq_hold', {x(20)}, 'sched_i', {x(21)}, 'faults', {x(22)}, 'w_est', {reshape(x(23:25), 3, 1)}, 'mag_seen', {(x(26) ~= 0)}, 'mag_age', {x(27)}, 'gyro_age', {x(28)}), x(29));
            y = [[double(o1.mode); double(o1.t); double(o1.t_mode); double(o1.hold); double(o1.ho); double(o1.ho_t); double(o1.ad_ok); double(o1.n_rej); reshape(o1.i_q, [], 1); double(o1.sz_sum); double(o1.sz_n); double(o1.sz_t0); double(o1.sigma); reshape(o1.s_prop, [], 1); double(o1.s_prop_ok); double(o1.acq_hold); double(o1.sched_i); double(o1.faults); reshape(o1.w_est, [], 1); double(o1.mag_seen); double(o1.mag_age); double(o1.gyro_age)]];
        case 'shared::qmult'
            [o1] = asils.relations.shared.qmult(reshape(x(1:4), 4, 1), reshape(x(5:8), 4, 1));
            y = [reshape(o1, [], 1)];
        case 'shared::qnorm'
            [o1] = asils.relations.shared.qnorm(reshape(x(1:4), 4, 1));
            y = [reshape(o1, [], 1)];
        case 'shared::skew'
            [o1] = asils.relations.shared.skew(reshape(x(1:3), 3, 1));
            y = [reshape((o1).', [], 1)];
        otherwise
            error('pcode:call', 'no function %s', name);
    end
end
